def is_Monotonic(A):
    if len(A) <= 2:
        return True

    increasing = True
    decreasing = True

    for i in range(1, len(A)):
        if A[i] < A[i-1]:
            increasing = False
        if A[i] > A[i-1]:
            decreasing = False

    return increasing or decreasing

def is_sublist(l, s):
    if not s:
        return True
    if len(s) > len(l):
        return False
    for i in range(len(l) - len(s) + 1):
        if l[i:i + len(s)] == s:
            return True
    return False

