def is_samepatterns(colors, patterns):
    """
    Check whether the colors sequence follows the pattern given in the patterns array.

    Args:
        colors: A list of color values
        patterns: A list of pattern values

    Returns:
        bool: True if the colors follow the pattern, False otherwise
    """
    if len(colors) != len(patterns):
        return False

    if len(colors) == 0:
        return True

    # Create mappings from colors to patterns and patterns to colors
    color_to_pattern = {}
    pattern_to_color = {}

    for color, pattern in zip(colors, patterns):
        # Check if color already maps to a different pattern
        if color in color_to_pattern:
            if color_to_pattern[color] != pattern:
                return False
        else:
            color_to_pattern[color] = pattern

        # Check if pattern already maps to a different color
        if pattern in pattern_to_color:
            if pattern_to_color[pattern] != color:
                return False
        else:
            pattern_to_color[pattern] = color

    return True
